const allTranslations = { ...translations, ...supplementalTranslations };

// Normalize strings to ignore line breaks and extra spaces from JSX formatting
const normalize = (str: string) => str.replace(/\s+/g, ' ').trim();

// Build i18next resources dynamically to prevent casing mismatches
const resources = {
  EN: { translation: {} as Record<string, string> },
  FR: { translation: {} as Record<string, string> },
  en: { translation: {} as Record<string, string> },
  fr: { translation: {} as Record<string, string> }
};

for (const [key, value] of Object.entries(allTranslations)) {
  const normalizedKey = normalize(key);
  resources.EN.translation[normalizedKey] = value.EN;
  resources.FR.translation[normalizedKey] = value.FR;
  resources.en.translation[normalizedKey] = value.EN;
  resources.fr.translation[normalizedKey] = value.FR;
}

i18n
  .use(LanguageDetector)
  .use(initReactI18next)
  .init({
    resources,
    fallbackLng: 'en',
    detection: {
      order: ['localStorage', 'navigator'],
      lookupLocalStorage: 'language', // Maps seamlessly to your old localStorage key
      caches: ['localStorage'],
    },
    interpolation: {
      escapeValue: false, // React inherently protects from XSS
    },
  });

export function LanguageProvider({ children }: { children: React.ReactNode }) {
  const { i18n: i18nInstance } = useTranslation();

  useEffect(() => {
    const lang = i18nInstance.language?.toLowerCase().startsWith('fr') ? 'fr' : 'en';
    document.documentElement.lang = lang;
  }, [i18nInstance.language]);

  return <>{children}</>;
}

export function useLanguage(): LanguageContextType {
  const { t: i18nT, i18n: i18nInstance } = useTranslation();
  
  const language = (i18nInstance.language?.toUpperCase().startsWith('FR') ? 'FR' : 'EN') as Language;
  
  const setLanguage = useCallback((lang: Language) => {
    i18nInstance.changeLanguage(lang.toLowerCase());
  }, [i18nInstance]);

  const t = useCallback((key: string) => {
    if (!key) return '';
    const normalizedKey = normalize(key);
    return i18nT(normalizedKey as any, { defaultValue: key }) as string;
  }, [i18nT]);

  return { language, setLanguage, t };
}
